mapper.sql:
WHERE a.user_id = #{userId}
AND EXISTS (SELECT 1 FROM attachment_student r WHERE r.attachment_id = a.id AND r.user_id = a.user_id AND r.student_id = #{studentId})
AND a.file_name LIKE CONCAT('%', #{keyword}, '%')
